import{_ as n,o as t,c as o,a4 as s}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse('{"title":"ADR-0014 — Un formulaire est un Content Type, pas une entité à part","description":"Extrait de docs/adr/0014-un-formulaire-est-un-content-type.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0014 — Un formulaire est un Content Type, pas une entité à part","description":"Extrait de docs/adr/0014-un-formulaire-est-un-content-type.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0014-un-formulaire-est-un-content-type.md","filePath":"developpeurs/adr/0014-un-formulaire-est-un-content-type.md"}'),r={name:"developpeurs/adr/0014-un-formulaire-est-un-content-type.md"};function i(a,e,u,l,c,d){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="adr-0014--un-formulaire-est-un-content-type-pas-une-entité-à-part" tabindex="-1">ADR-0014 — Un formulaire est un Content Type, pas une entité à part <a class="header-anchor" href="#adr-0014--un-formulaire-est-un-content-type-pas-une-entité-à-part" aria-label="Permalink to &quot;ADR-0014 — Un formulaire est un Content Type, pas une entité à part {#adr-0014--un-formulaire-est-un-content-type-pas-une-entité-à-part}&quot;">​</a></h1><p><strong>Date :</strong> 20 août 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> CDC_CMS_AI_Native_v1.1 §7 (formulaires avancés, parcours de soumission, SVE), §3 (Content Engine), §4.1 (bloc <code>Form</code>) ; plan d&#39;action agile §5 (V1.1, « E11 — Formulaires avancés »)</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Le bloc <code>Form</code> du Core existe depuis l&#39;Epic E2 : <code>FormBlock(type=&quot;form&quot;, form_id: uuid.UUID, …)</code>. C&#39;était, jusqu&#39;ici, une <strong>référence en attente</strong> — rien dans le dépôt ne définissait ce qu&#39;un <code>form_id</code> désignait. Combler cette référence est le cœur de l&#39;Epic E11, et cela oblige à trancher une question que le CDC ne détaille pas : <em>de quelle nature est un formulaire dans ce CMS ?</em></p><p>L&#39;enjeu n&#39;est pas cosmétique. Trois faits du dépôt le rendent structurant :</p><ol><li><strong>L&#39;archétype 5 du CDC §3.1, « contenu généré par formulaire », existe déjà</strong> et la SVE l&#39;utilise (<code>ContentTypeBlueprint(archetype=&quot;contenu_genere_par_formulaire&quot;)</code>, E7). Une demande de saisine <em>est</em> un enregistrement de contenu.</li><li><strong>Le schéma des champs d&#39;un formulaire est déjà exprimable</strong> : <code>ContentTypeSchema</code>, une liste de <code>FieldDefinition</code> (E1), stockée en JSONB dans <code>content_types.schema</code>. Le Field Engine sait déjà valider, typer, et déclarer les données personnelles champ par champ.</li><li><strong>Le critère de recette du Plugin SDK (E7) en dépend.</strong> La SVE doit rester constructible sans toucher au Core ; or un plugin sait déjà provisionner un Content Type (une ligne, pas une migration). S&#39;il fallait provisionner <em>en plus</em> une entité « formulaire », il faudrait un second mécanisme d&#39;installation.</li></ol><p>Trois rangements étaient possibles :</p><ul><li>une <strong>table <code>forms</code></strong> dédiée, avec sa propre définition de champs ;</li><li>une <strong>table <code>forms</code></strong> qui référencerait un Content Type pour son schéma ;</li><li>une <strong>colonne de configuration sur <code>content_types</code></strong>, à côté de <code>listing_config</code> (E3) et <code>lifecycle_rules</code> (E4).</li></ul><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>Un formulaire est un Content Type qui porte une <code>form_config</code>.</strong> La configuration vit dans <code>content_types.form_config</code> (JSONB, nullable), typée par <code>FormConfig</code> (<code>app/forms/config.py</code>). <code>FormBlock.form_id</code> désigne donc un <code>content_types.id</code>, et le bloc du Core n&#39;a pas eu à changer d&#39;une ligne.</p><p>Le critère qui tranche est celui que la docstring d&#39;<code>app/models/content.py</code> pose depuis E3 : <strong>une propriété qui décrit comment un Content Type se comporte n&#39;a pas d&#39;existence propre.</strong> Une vue liste n&#39;existe pas sans le type qu&#39;elle présente (<code>listing_config</code>) ; une règle de cycle de vie n&#39;existe pas sans le type auquel elle s&#39;applique (<code>lifecycle_rules</code>) ; un formulaire n&#39;existe pas sans les champs qu&#39;il fait remplir. Les trois sont la même catégorie de chose, et <code>form_config</code> est la troisième colonne de cette famille.</p><p>Quatre conséquences en découlent, et ce sont elles qui motivent la décision :</p><ol><li><strong>Déclarer un formulaire est une écriture de données.</strong> Le critère de recette n°1 du CDC (§3.1) s&#39;étend aux formulaires sans effort : <code>POST /api/v1/content-types</code> accepte <code>form_config</code>, donc un webmaster crée « Proposer une actualité » en un appel, sans code et <strong>sans plugin</strong>. Une table <code>forms</code> aurait exigé une route de création de plus, et un formulaire serait devenu quelque chose qu&#39;on « développe ».</li><li><strong>Un plugin déclare un formulaire complet par son manifeste.</strong> <code>ContentTypeBlueprint.form_config</code> est provisionné dans la même écriture que le Content Type. Sans cela, il aurait existé un instant — entre les deux écritures — où le bloc <code>Form</code> peut désigner un type qui refuse toute soumission.</li><li><strong>Une soumission est un <code>ContentEntry</code>, donc tout le Core s&#39;y applique gratuitement</strong> : le panneau de configuration (E4), le workflow éditorial et son statut <code>draft</code>, l&#39;ACL (E6), le journal RGPD par drapeau <code>contains_personal_data</code> (E5), l&#39;index lexical (E3), les règles de cycle de vie. Une table <code>form_submissions</code> autonome aurait rejoué chacun de ces mécanismes, ou s&#39;en serait passée — c&#39;est-à-dire aurait produit des données personnelles hors du régime RGPD du reste du CMS.</li><li><strong>Le Field Engine reste le seul vocabulaire de champs.</strong> Les cinq ajouts du CDC §7.1 (<code>captcha</code>, <code>field_group</code>, <code>field_help</code>, <code>conditional logic</code>, <code>likert_scale</code>) sont des types et attributs de <code>BaseFieldDef</code>, donc disponibles aussi bien à un formulaire qu&#39;à un Content Type éditorial, à un réglage de panneau ou à la charge utile d&#39;un bloc de plugin. Un vocabulaire de champs propre aux formulaires aurait divergé du premier au deuxième type ajouté.</li></ol><h3 id="la-table-form_submissions-et-pourquoi-elle-est-justifiée" tabindex="-1">La table <code>form_submissions</code>, et pourquoi elle <strong>est</strong> justifiée <a class="header-anchor" href="#la-table-form_submissions-et-pourquoi-elle-est-justifiée" aria-label="Permalink to &quot;La table `form_submissions`, et pourquoi elle **est** justifiée {#la-table-form_submissions-et-pourquoi-elle-est-justifiée}&quot;">​</a></h3><p>Une seule table nouvelle porte le parcours : <code>form_submissions</code>. Elle n&#39;est pas un second stockage du contenu — à la confirmation, un <code>ContentEntry</code> est créé et <code>entry_id</code> pointe dessus. Elle existe parce que le parcours du CDC §7.2 a un <strong>état intermédiaire qui n&#39;appartient à personne d&#39;autre</strong> : une saisie validée, relue, mais pas encore confirmée.</p><p>Deux façons de tenir cet état étaient possibles : un jeton signé renvoyé au navigateur, ou une ligne en base. <strong>Le jeton a été écarté pour deux motifs cumulés :</strong></p><ul><li><em>RGPD</em> : un formulaire de saisine contient un nom, une adresse, parfois un motif médical. Les faire voyager dans un jeton, fût-il signé, les expose dans un historique de navigation, un journal de proxy, un lien partagé.</li><li><em>La garantie centrale de l&#39;Epic</em> : « la page de relecture n&#39;est jamais contournable » ne se démontre que si la confirmation <strong>ne peut accepter aucune donnée</strong>. Avec une ligne en base, <code>confirm_submission()</code> ne reçoit qu&#39;une soumission déjà enregistrée — il n&#39;existe aucun paramètre par lequel des valeurs entreraient. Avec un jeton, la donnée entrerait au moment de la confirmation et la garantie reposerait sur une vérification de signature, c&#39;est-à-dire sur du code qu&#39;un refactor peut affaiblir, plutôt que sur la forme des choses.</li></ul><p>La même logique commande deux <code>Literal</code> à valeur unique dans <code>FormConfig</code> : <code>review_step: Literal[&quot;always&quot;]</code> et <code>captcha: Literal[&quot;required&quot;]</code>. Un booléen <code>review_step_enabled</code> aurait suffi à ce qu&#39;un formulaire arrive un jour en production avec <code>false</code> — par un import, une reprise de données, un administrateur pressé. Ici, la valeur « désactivé » n&#39;est pas refusée à l&#39;exécution : elle est <strong>inexprimable</strong> dans la donnée stockée. Le jour où le CDC changerait d&#39;avis, l&#39;union s&#39;ouvrirait, et ce serait un choix visible dans un diff.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Table <code>forms</code> autonome, avec sa propre définition de champs</strong></td><td>Écartée : elle duplique le Field Engine. Deux vocabulaires de champs auraient divergé au premier type ajouté, et l&#39;admin aurait dû savoir rendre deux familles de widgets. Surtout, les soumissions seraient sorties du régime RGPD, du workflow et de l&#39;ACL du reste du CMS — c&#39;est-à-dire que les données les plus sensibles du site auraient été celles avec le moins de garanties.</td></tr><tr><td><strong>Table <code>forms</code> référençant un Content Type pour son schéma</strong></td><td>Écartée : elle conserve le Field Engine mais ajoute une entité sans existence propre (un formulaire ne survit pas au type dont il fait remplir les champs) et une seconde ligne à provisionner à l&#39;installation d&#39;un plugin. Elle aurait aussi rouvert la question « que se passe-t-il si deux formulaires pointent le même Content Type ? », à laquelle aucun besoin du corpus ne répond.</td></tr><tr><td><strong>Colonnes SQL dédiées sur <code>content_types</code></strong></td><td>Écartée pour la même raison qu&#39;en ADR-0013 : une migration pour une configuration dont on sait qu&#39;elle va grandir (destinataires, correspondances de champs, pré-remplissage), alors que le patron <code>listing_config</code> / <code>lifecycle_rules</code> existe précisément pour accueillir cela sans migration. Le typage revient par Pydantic.</td></tr><tr><td><strong>Garder l&#39;état intermédiaire dans un jeton signé côté client</strong></td><td>Écartée : cf. ci-dessus. Elle aurait évité une table, au prix de faire circuler des données personnelles et d&#39;affaiblir la garantie non contournable de la page de relecture.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li><code>FormBlock.form_id</code> a enfin un référent, sans qu&#39;une ligne du bloc d&#39;E2 change.</li><li>Un formulaire se déclare par une écriture de données, par un webmaster comme par un manifeste de plugin.</li><li>Les soumissions héritent gratuitement du workflow, du RGPD, de l&#39;ACL, de l&#39;index et du panneau de configuration.</li><li>La SVE complète (formulaire public, tableau de bord, export CSV, fil de discussion) reste un plugin : trois points d&#39;extension de plus au SDK, aucune exception.</li><li>« La page de relecture n&#39;est pas contournable » et « le captcha est exigé » sont portés par la <strong>forme</strong> des données et des signatures, pas par des vérifications à l&#39;exécution.</li></ul><p><strong>Négatives</strong></p><ul><li><strong>Un Content Type ne peut porter qu&#39;un seul formulaire.</strong> Deux formulaires publics sur les mêmes champs (une version courte et une version longue) demandent deux Content Types, donc deux ensembles d&#39;enregistrements. Aucun besoin du corpus ne l&#39;exige aujourd&#39;hui ; le jour où il se présentera, ce sera une vraie décision — probablement une liste de configurations plutôt qu&#39;une table.</li><li><strong><code>form_submissions</code> référence <code>content_entries</code> par une clé étrangère <code>SET NULL</code>.</strong> Supprimer un contenu laisse donc un dossier sans contenu : c&#39;est délibéré (la preuve d&#39;un dépôt survit à ce qui a été déposé), mais cela produit des lignes qu&#39;un écran de guichet doit savoir afficher sans planter.</li><li><strong>La configuration de formulaire n&#39;est pas multilingue</strong>, comme <code>settings.seo</code> (ADR-0013) et pour la même raison. Les clés i18n (<code>title_key</code>, <code>submit_label_key</code>, <code>review_intro_key</code>) couvrent les libellés d&#39;interface ; les libellés de champs, eux, vivent dans <code>content_types.schema</code>, et l&#39;Epic multilingue devra les trancher en même temps que le reste.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Epic E12 (comptes usagers) : brancher une source de pré-remplissage sur <code>register_prefill_source()</code> — le point d&#39;extension est posé et vide (<code>app/forms/prefill.py</code>). → <strong>Close</strong> par <code>fa25069</code> (20/08/2026) : <code>app/composition.py</code> branche <code>register_prefill_source(end_user_profile_attributes)</code> (<code>apps/api/app/composition.py:195-196</code>, source dans <code>app/end_users/prefill.py</code>). Cochée le 26/09/2026 (audit du 26/09, SUIVI-1).</li><li>[ ] Epic multilingue : trancher la déclinaison par locale de <code>content_types.schema</code> et de <code>form_config</code>, en même temps que <code>settings.seo</code>.</li><li>[x] Exploitation : brancher un ordonnanceur sur <code>purge_expired_submissions()</code> (saisies abandonnées) et sur <code>pending_deliveries()</code> (ré-essais de notification), comme pour le balayage de cycle de vie d&#39;E4. → <strong>Close</strong> par l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0027-adaptateurs-d-exploitation-livres-inactifs">ADR-0027</a> (14/09/2026) ; tâches décrites à la notice §6.3.</li></ul>',27)])])}const g=n(r,[["render",i]]);export{m as __pageData,g as default};
